```latex
\section{Preliminaries}
\label{sec:preliminaries}

\subsection{Levin reductions}
\label{subsec:prelim-Levin-reductions}

A search problem for us is a relation $R \subseteq \{ 0,1\}^* \times \{ 0,1\}^*$. A search problem $R$ is in $\FP$ if there exists a polynomial-time function that on input $x$, outputs some $y$ such that $(x, y) \in R$, if such a $y$ exists.

\subsection{Proof complexity}
\label{subsec:proof-complexity}
Following the classical definition of \citeauthor{CR79} \cite{CR79}, a \emph{propositional proof system} $S$ for the set~$\TAUT$ of propositional tautologies is a polynomial-time function $S : \{ 0,1\}^* \to \TAUT$ whose range is exactly $\TAUT$. We think of $S$ at the polynomial-time verifier mapping proofs to the statements they prove; i.e., if $S(\pi) = \varphi$, then we say $\pi$ is an $S$-proof of $\varphi$.

For a tautology $\varphi$ and a proof system $S$, we denote by $\size{S}{\varphi} \coloneq \min_{\pi : S(\pi) = \varphi} |\pi| $ the \emph{size} of its smallest $S$-proof. A proof system $S$ is \emph{polynomially bounded} if there exists a constant~$c \in \bbN$ such that for all $\varphi \in \TAUT$ we have $\size{S}{\varphi} \leq |\varphi|^c$. 
\newcommand{\effproves}{\vdash_{\operatorname{poly}}}
For a sequence $\varphi = \{\varphi_n\}_{n\in\bbN}$ of tautologies, we write $S \effproves \varphi$ or simply $S \effproves \varphi_n$ to express that $\size{S}{\varphi_n} = |\varphi|^{O(1)}$ as $n$ grows.
When we want to emphasize that it is via a specific proof $\pi$ that $S$ proves $\varphi_n$, we write $\pi : S\vdash\varphi_n$. More generally, for $s \in \bbN$, we write $S\vdash_{s} \varphi_n$ to express that there exists an~$S$-proof $\pi$ of size $|\pi| \leq s$ such that~$\pi : S \vdash \varphi_n$.

A \emph{literal} is a propositional variable or its negation. Given a formula $\varphi(x_1, \dots, x_n)$, a \emph{literal substitution} is a mapping of the form $\rho : \{ x_1, \dots, x_n\} \to \{x_1, \dots, x_n, \neg x_1, \dots, \neg x_n, 0, 1\}$ that replaces variables by other literals or substitutes constants in their place. We denote by $\varphi_{\restriction \rho}$ the substituted formula $\varphi(\rho(x_1), \dots, \rho(x_n))$, with the convention that every resulting occurrence of $\neg\neg x_i$ is replaced by $x_i$. A \emph{restriction} is a particular case of a variable substitution, where all variables are mapped to either $0$, $1$, or themselves. We say that a proof system~$S$ is \emph{closed under substitutions} (respectively, \emph{closed under restrictions}) if there exists a constant $d\in \bbN$ such that for every tautology $\varphi$ and every literal substitution (respectively, restriction) $\rho$, it holds that $\size{S}{\varphi_{\restriction \rho}} \leq \size{S}{\varphi}^d$. All the explicit proof systems dealt with in this work (i.e., the ones described below, like Resolution or Frege or Extended Frege systems) are closed under literal substitutions. In these cases, a proof of the substituted formula can be obtained directly by applying the substitution line by line to every formula appearing in a proof $\pi$ of $\varphi$, and we hence denote by $\pi_{\restriction\rho}$ the corresponding substituted proof of~$\varphi_{\restriction \rho}$. 

\subsubsection{Resolution}
\label{subsec:prelim-resolution}
A central proof system in this work is Resolution ($\Res$). We usually see this as a refutation system for CNF formulas. Accordingly, we sometimes write $\pi : \Res\ \vdash \neg\varphi$ for a CNF formula $\varphi$, to mean that $\pi$ is a Resolution refutation of $\varphi$, hence a proof of the tautology $\neg\varphi$.

A \emph{literal} is a propositional atom or its negation, a \emph{clause} is a disjunction of literals, and a \emph{CNF formula} is a conjunction of clauses. We see clauses as sets of literals, and write simply $C \subseteq D$ to express that $C$ is a subclause of $D$.  A \emph{Resolution refutation} of an unsatisfiable CNF formula $\varphi = C_1 \land \dots \land C_m$ over variables~$x_1, \dots, x_n$ is a sequence $D_1, \dots, D_s$ of clauses over $x_1, \dots, x_n$ such that $D_s = \bot$, denoting the empty clause, and for every $i \in [s-1]$, the clause $D_i$ either (a) is one of the clauses $C_1, \dots, C_m$ of $\varphi$, or (b) is a \emph{weakening} of a previous clause, meaning that $D_i \supseteq D_j$ for some $1\leq j < i$, or (c) has been obtained from two previous clauses $D_j = A \lor x$ and $D_k = B \lor \neg x$, for~$j, k < i$, by an application of the \emph{Resolution rule}:
    \begin{prooftree}
        \AxiomC{$A \lor x$}
        \AxiomC{$B \lor \neg x$}
        \RightLabel{\footnotesize{\;\;(Res)}}
        \BinaryInfC{$A \lor B$}
    \end{prooftree}
We say that $A \lor B$ was obtained by \emph{resolving} over $x$.
The \emph{length} of $\pi$, denoted by $\prooflength{\pi}$, is $s$.

To every Resolution refutation $\pi$ we can associate a directed acyclic graph in a natural way, and we often do so implicitly.

\subsection{The $\Reff$ formulas}
\label{subsec:prelim-Reff}

\paragraph{The variables of $\Reff_s(\varphi)$.}
\label{subsec:vars-of-reff}
Here, we assume $\varphi$ is a CNF formula over $n$ variables $x_1, \dots, x_n$ and $m$ clauses and define the following variables, where $\Lit_n \coloneq \{x_1, \dots, x_n, \neg x_1, \dots, \neg x_n\}$.

\bigskip
\begin{tabular}{lll}
    $\alit^A_\ell$ & : & literal $\ell \in \Lit_n$ is present in the clause $A \in [m]$ of $\varphi$; \\
    $\enable^B$ & : & block $B \in [s]$ is enabled; \\
    $\derived^B$ & : & block $B\in [s]$ was obtained by a Resolution step;\\ 
    $\weak^B_A$ & : & block $B\in[s]$ is obtained by weakening from clause $A \in [m]$ of $\varphi$; \\
    $\lit^B_\ell$ & : & literal $\ell\in\Lit_n$ is present in the block $B\in[s]$; \\
    $\res^B_{x_i}$ & : & block $B\in[s]$ was obtained by resolving over the variable $x_i$; \\
    $\lpoint^B_{B'}$ & : & block $B \in [s]$ was resolved on the left from block $B' \in [s]$, $B'<B$; \\
    $\rpoint^B_{B'}$ & : & block $B\in[s]$ was resolved on the right from block $B' \in [s]$, $B'<B$.
\end{tabular}
\bigskip

Building on these variables, the $\Reff_s(\varphi)$ formula is defined as follows. We write the clauses as implications for the sake of readability.

\begin{definition}[The $\Reff$ formulas]
\label{def:Reff-formulas}
Let $n, m, s \in \bbN$, and let $\Lit_n \coloneq \{x_1, \dots, x_n, \neg x_1, \dots, \neg x_n\}$ denote the of possible literals over $n$ variables. The $\Reff_s(\varphi)$ formula is built from the variables defined above, together with the conjunction of the following clauses:

{\allowdisplaybreaks
    \begin{axiomdef}{2}{\textsc{Ref}}
        & \left( \enable^B \land \res^B_{x_i} \land \lpoint^B_{B'} \land \lit^{B'}_\ell \right) \to \lit^{B}_\ell  &&\quad\text{ for }B, B'\in[s], B' < B, i\in[n], \ell \in \Lit_n \setminus \{ x_i\},\label{axiom:must-appear-after-res-left} \\
        & \left( \enable^B \land \res^B_{x_i} \land \rpoint^B_{B'} \land \lit^{B'}_\ell \right) \to \lit^{B}_\ell  &&\quad\text{ for }B, B'\in[s], B' < B, i\in[n], \ell \in \Lit_n \setminus \{\neg x_i\},\label{axiom:must-appear-after-res-right}\\
        & \left( \enable^B \land \weak^B_A \land \alit^A_\ell\right) \to \lit^B_\ell  &&\quad\text{ for }B\in[s], A\in[m], \ell\in \Lit_n,\label{axiom:must-appear-after-weak}\\
        & \left( \enable^B \land \derived^B \right ) \to \bigvee_{i\in[n]} \res^B_{x_i}  &&\quad\text{ for }B \in [s],\label{axiom:must-resolve} \\
        & \left( \enable^B \land \derived^B \right ) \to \bigvee_{\substack{B' \in [s] \\ B' < B}} \lpoint^B_{B'}  &&\quad\text{ for 
        }B \in [s],\label{axiom:must-point-left} \\
        & \left( \enable^B \land \derived^B \right ) \to \bigvee_{\substack{B' \in [s] \\ B' < B}} \rpoint^B_{B'}  &&\quad\text{ for }B \in [s],\label{axiom:must-point-right} \\
        & \left( \enable^B \land  \neg \derived^B \right) \to \bigvee_{A\in[m]} \weak^B_A  &&\quad\text{ for }B \in [s],\label{axiom:must-weaken} \\
        & \left( \enable^B \land  \lpoint^B_{B'} \right) \to \enable^{B'}  &&\quad\text{ for }B, B' \in [s], B' < B\label{axiom:must-enable-left} \\
        & \left( \enable^B \land  \rpoint^B_{B'} \right) \to \enable^{B'}  &&\quad\text{ for }B, B' \in [s], B' < B\label{axiom:must-enable-right} \\
        & \neg \lit^s_\ell &&\quad\text{ for }\ell \in \Lit_n ,\label{axion:root-empty}\\
        & \enable^s. && \label{axiom:root-enabled}
    \end{axiomdef}
}\end{definition}

\paragraph{Blocks and block-width.}
If a variable is part of a block $B_i$, we say that it \emph{mentions} $B_i$. An important measure for us will be the \emph{block-width} of a given clause $C$ over the variables of $\Reff_s(\varphi)$. This is defined as the number of different blocks mentioned by the variables of the literals in $C$, not counting the root block~$B_\bot$. We denote this measure by $\bw(C)$, and generalize it to refutations by taking $\bw(\pi)$ to be the maximum block-width over all the clauses in $\pi$.

\section{The Proof Analysis Problem: definitions and basic facts}
\label{sec:PAP-def}

\begin{definition}[The Proof Analysis Problem, $\PAP_Q$]
    \label{def:PAP}
    Let $Q$ be a propositional proof system. We define the \emph{Proof Analysis Problem for $Q$} to be the language
    \[ \PAP_Q \coloneq \{ (\varphi, \pi, 1^s) \mid \varphi \in \SAT \text{ and } \pi : {Q \vdash \neg \Reff_s(\varphi)} \}.\]
    We denote by $\PAP_Q[s(n)]$ the problem where the size parameter $s$ is restricted to be at least $s(n)$ and $n$ denotes the number of variables of $\varphi$.
\end{definition}

\begin{definition}[Search version of $\PAP$]
    For a propositional proof system $Q$, we denote by $\FPAP_Q$ the \emph{search version of the Proof Analysis Problem for $Q$}, defined as follows.
    \searchProblemStatement{$\FPAP_Q$ (search version of $\PAP_Q$)}{A CNF formula $\varphi$, a size parameter $s$ in unary and a proof $\pi$ such that $\pi : Q \vdash \neg \Reff_s(\varphi)$.}{Either a satisfying assignment for $\varphi$, if $\varphi \in \SAT$, or $0$ otherwise.}
    Similarly to $\PAP_Q[s(n)]$, we define $\FPAP_Q[s(n)]$ to be the search problem where the size parameter is at least $s(n)$. 
\end{definition}

\section{The extraction algorithm}
\label{sec:the-algorithm}

\subsection{The block-width reduction algorithm}
\label{subsec:width-reduction-algorithm}

\begin{definition}[Disabling restrictions]
    \label{def:disabling-restriction}
    We say that a restriction $\rho\in\{0,1, *\}^N$ to the $N$ variables of $\Reff_s(\varphi)$ is \emph{$d$-disabling} if it satisfies that (i) exactly $d$ blocks are disabled, and the rest are all enabled, (ii) every variable belonging to a disabled block is assigned a value, and (iii) no other variable is assigned.
\end{definition}

\subsection{The block-width analysis algorithm}\
\label{subsec:width-analysis-algo}

\begin{fact}
    \label{fact:weakening}
    Let $\varphi$ be a Boolean formula in CNF over $n$ variables. If $C$ is a width-$n$ clause over the variables of $\varphi$ that is not the weakening of any clause of $\varphi$, then $\neg C$ encodes a satisfying assignment for $\varphi$.
\end{fact}
